    category: 'sekou',
    question: '鉄骨工事（建方・溶接）の施工管理に関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '現場溶接は、天候にかかわらず常に同一の条件で行えるため、風雨等に対する養生や作業条件の管理は特に必要とされない。', explanation: '不適当。現場溶接は風によるシールドガスの乱れや、雨天時の感電・品質低下のおそれがあるなど、天候の影響を受けやすい作業であり、養生や作業条件の管理が品質確保上重要とされる。「管理は不要」というのは誤りである。' },
      { key: 'B', text: '現場溶接は、天候（風・雨）の影響を受けやすいため、養生や作業条件の管理が品質確保上重要である。', explanation: '適当。風は溶接部のシールドガスを乱し、雨は感電・品質低下のおそれがあるため、養生等の管理が必要である。' },
      { key: 'C', text: '高力ボルトの本締めは、ボルト群ごとに中央から端部へ向かう等、施工手順（締付け順序）に配慮して行うことが望ましい。', explanation: '適当。不均一な締付けは接合部の応力集中を招くおそれがあるため、順序に配慮した締付けが望ましいとされる。' },
      { key: 'D', text: '鉄骨建方の精度管理には、建入れ検査（垂直度・レベル等の確認）が含まれる。', explanation: '適当。建方後に建入れ検査を行い、規定の精度内にあることを確認することが品質管理上重要である。' },
    ],
